<script setup lang="ts">
import {strategyRequest} from '~/utils/strategy-api';

import type {StrategyGroup} from '#shared/domain/strategy';
import WorkflowDialog from './WorkflowDialog.vue';
import ChoiceListbox from './ChoiceListbox.vue';
const account=useWorkflowAccount(),state=useShowcase();
const items=ref<StrategyGroup[]>([]),mine=ref(false),q=ref(''),platform=ref(''),busy=ref(false),error=ref(''),open=ref(false),deleting=ref<StrategyGroup|null>(null),deleteOpen=ref(false);
const empty=()=>({id:undefined as string|undefined,revision:0,name:'',region:'',platform:'QQ',description:'',contact:'',url:'',expiresAt:new Date(Date.now()+30*86400000).toISOString().slice(0,10),public:true,consent:false});
const form=reactive(empty());
const visible=computed(()=>items.value.filter(g=>[g.name,g.region,g.description].join(' ').toLowerCase().includes(q.value.toLowerCase())&&(!platform.value||g.platform===platform.value)));
async function load(){busy.value=true;error.value='';try{const d=await strategyRequest<{items:StrategyGroup[]}>('/api/workflow/groups',{query:mine.value?{mine:'1'}:{}});items.value=d.items;}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'社群读取失败';}finally{busy.value=false;}}
function create(){if(!account.user.value){state.utility.value='account';return;}Object.assign(form,empty());open.value=true;}
function edit(g:StrategyGroup){Object.assign(form,g,{expiresAt:g.expiresAt.slice(0,10),consent:false});open.value=true;}
async function save(){busy.value=true;error.value='';try{await strategyRequest('/api/workflow/groups',{method:'POST',body:{...form,expiresAt:form.expiresAt+'T23:59:59+08:00'}});open.value=false;await load();}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'发布失败，请检查资料';}finally{busy.value=false;}}
async function remove(){if(!deleting.value)return;try{await strategyRequest('/api/workflow/groups',{method:'DELETE',body:{id:deleting.value.id,revision:deleting.value.revision}});deleteOpen.value=false;await load();}catch(e){error.value=(e as {data?:{message?:string}}).data?.message||'删除失败';}}
watch(mine,()=>void load());onMounted(()=>void load());
</script>
<template><section class="player-groups"><header class="learn-heading"><div><p class="reading-kicker">一起对局</p><h2>找到附近或线上的同好</h2></div><button class="p-button" @click="create">发布我的社群 ＋</button></header><div class="article-search"><label>地区或名称<input v-model="q" type="search" placeholder="城市、线上或社群名称" /></label><ChoiceListbox v-model="platform" label="平台" :options="[{value:'',label:'全部平台'},...['QQ','微信','Discord','其他'].map(p=>({value:p,label:p}))]" /><button :aria-pressed="mine" :disabled="!account.user.value" @click="mine=!mine">{{ mine?'查看全部社群':'我的发布' }}</button></div><p v-if="busy" role="status">正在读取…</p><p v-if="error" role="alert">{{ error }}<button @click="load">重试</button></p><div class="player-groups-grid"><article v-for="g in visible" :key="g.id"><small>{{ g.region }} · {{ g.platform }}</small><h3>{{ g.name }}</h3><p>{{ g.description }}</p><details><summary>查看加入方式</summary><p class="group-contact">{{ g.contact }}</p><a v-if="g.url" :href="g.url" target="_blank" rel="noopener noreferrer">打开邀请链接 ↗</a></details><footer><small>{{ g.author }} · 有效至{{ new Date(g.expiresAt).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}) }}{{ !g.public?' · 已撤回':'' }}</small><template v-if="g.canEdit"><button @click="edit(g)">编辑／撤回</button><button @click="deleting=g;deleteOpen=true">删除</button></template></footer></article></div><div v-if="!busy&&!error&&!visible.length" class="reading-empty"><h3>暂无符合条件的社群</h3><p>发布真实的社群名片，让同好找到你。</p><button class="p-button" @click="create">发布社群</button></div>
<WorkflowDialog v-model:open="open" title="社群名片" description="加入方式仅展示在这张公开名片上，不会写入账号公开资料。"><form class="workflow-form" @submit.prevent="save"><label>社群名称<input v-model="form.name" maxlength="60" required /></label><label>地区<input v-model="form.region" maxlength="40" placeholder="例如：上海、线上" required /></label><ChoiceListbox v-model="form.platform" label="平台" :options="['QQ','微信','Discord','其他'].map(p=>({value:p,label:p}))" /><label>简介<textarea v-model="form.description" maxlength="1000" rows="4" required /></label><label>加入方式<input v-model="form.contact" maxlength="300" placeholder="群号、验证说明或联系办法" required /></label><label>邀请链接（可选）<input v-model="form.url" type="url" maxlength="2000" /></label><label>有效期<input v-model="form.expiresAt" type="date" required /></label><label class="strategy-consent"><input v-model="form.public" type="checkbox" />公开展示</label><label class="strategy-consent"><input v-model="form.consent" type="checkbox" required />我确认这些加入信息可以随名片公开</label><p v-if="error" role="alert">{{ error }}</p><button class="p-button" type="submit" :disabled="busy">保存名片</button></form></WorkflowDialog><WorkflowDialog v-model:open="deleteOpen" title="删除社群名片"><p>{{ deleting?.name }}</p><button class="p-button" @click="remove">确认删除</button></WorkflowDialog></section></template>
